const twoProCanConsumeFixedParticle = (
  pattern: string,
  particleEndIndex: number
): boolean => {
  const nextChar = pattern.charAt(particleEndIndex);
  return (
    !nextChar ||
    /\s/.test(nextChar) ||
    /[?.!,;:'"“”‘’]/.test(nextChar) ||
    nextChar === '['
  );
};

const twoProCompileKoEnRule = (
  patternKo: string,
  templateEn: string
): TwoProKoEnCompiledRule | null => {
  if (!/\[[A-Za-z][A-Za-z0-9_]*\]/.test(patternKo)) {
    return null;
  }

  const normalizedPattern = String(patternKo || '').normalize('NFC');
  const placeholderRegex = /\[([A-Za-z][A-Za-z0-9_]*)\]/g;

  const slots: string[] = [];
  let regexSource = '^\\s*';
  let cursor = 0;
  let match: RegExpExecArray | null;

  while ((match = placeholderRegex.exec(normalizedPattern)) !== null) {
    regexSource += twoProLiteralToRegex(
      normalizedPattern.slice(cursor, match.index)
    );

    const token = match[1];
    slots.push(token);
    regexSource += '(.+?)';

    cursor = match.index + match[0].length;

    for (const marker of TWO_PRO_PARTICLE_MARKERS) {
      if (!normalizedPattern.startsWith(marker.text, cursor)) {
        continue;
      }

      const markerEnd = cursor + marker.text.length;

      if (
        marker.fixed &&
        !twoProCanConsumeFixedParticle(normalizedPattern, markerEnd)
      ) {
        continue;
      }

      regexSource += marker.regex;
      cursor = markerEnd;
      placeholderRegex.lastIndex = cursor;
      break;
    }
  }

  regexSource += twoProLiteralToRegex(normalizedPattern.slice(cursor));
  regexSource += '\\s*$';

  const literalLength = normalizedPattern
    .replace(/\[[A-Za-z][A-Za-z0-9_]*\]/g, '')
    .replace(/\s+/g, '')
    .replace(/[?.!,;:'"“”‘’/()]/g, '')
    .length;

  try {
    return {
      patternKo,
      templateEn,
      regex: new RegExp(regexSource, 'i'),
      slots,
      specificity: literalLength * 10 - slots.length,
    };
  } catch (error) {
    console.error('[한영 JSON 템플릿 정규식 생성 실패]', {
      patternKo,
      error,
    });

    return null;
  }
};

const TWO_PRO_KO_EN_TEMPLATE_RULES: TwoProKoEnCompiledRule[] =
  Object.entries(customRules)
    .map(([patternKo, templateEn]) =>
      twoProCompileKoEnRule(patternKo, String(templateEn))
    )
    .filter(
      (rule): rule is TwoProKoEnCompiledRule =>
        Boolean(rule)
    )
    .sort((a, b) => b.specificity - a.specificity);

const twoProBaseSlotType = (token: string): string => {
  return String(token || '')
    .toUpperCase()
    .replace(/\d+$/, '');
};

const twoProCleanCapturedKo = (value: string): string => {
  return String(value || '')
    .normalize('NFC')
    .replace(/^[\s"'“”‘’]+|[\s"'“”‘’]+$/g, '')
    .replace(/[?.!,;:]+$/g, '')
    .trim();
};

const twoProKoreanNumberToDigit = (value: string): string | null => {
  const normalized = String(value || '').trim();

  if (/^\d+$/.test(normalized)) {
    return normalized;
  }

  const map: Record<string, string> = {
    '한': '1',
    '하나': '1',
    '두': '2',
    '둘': '2',
    '세': '3',
    '셋': '3',
    '네': '4',
    '넷': '4',
    '다섯': '5',
    '여섯': '6',
    '일곱': '7',
    '여덟': '8',
    '아홉': '9',
    '열': '10',
  };

  return map[normalized] || null;
};

// ============================================================================
// ☆ TwoPro v9.29-safe: 모든 슬롯 경로의 기간 숫자 표기 통합
//
// 기존 rules-ko-en.json 슬롯 경로:
// 1일 → 1 day
//
// 최근 문장 엔진 경로:
// 1일 → one day
//
// 두 경로가 서로 다른 함수를 사용하던 문제를 해결하기 위해
// 레거시 슬롯 함수도 동일한 자연 표기 원칙을 적용합니다.
// ============================================================================
const twoProTranslateDuration = (value: string): string | null => {
  const cleanValue = twoProCleanCapturedKo(value)
    .replace(/\s*동안$/gu, '')
    .trim();

  // 이미 영어 기간 표현이면 그대로 유지합니다.
  if (
    /^(?:a|an|one|two|three|four|five|six|seven|eight|nine|ten|\d+)\s+(?:day|week|month|year|hour|minute)s?$/i.test(
      cleanValue
    )
  ) {
    return cleanValue;
  }

  const durationMatch = cleanValue.match(
    /^(\d+|한|하나|두|둘|세|셋|네|넷|다섯|여섯|일곱|여덟|아홉|열)\s*(년|개월|달|주|일|시간|분)$/u
  );

  if (!durationMatch) {
    return null;
  }

  const sourceNumber = durationMatch[1];

  const digit =
    twoProKoreanNumberToDigit(
      sourceNumber
    );

  if (!digit) {
    return null;
  }

  const unitMap: Record<string, string> = {
    '년': 'year',
    '개월': 'month',
    '달': 'month',
    '주': 'week',
    '일': 'day',
    '시간': 'hour',
    '분': 'minute',
  };

  const unit = unitMap[durationMatch[2]];

  if (!unit) {
    return null;
  }

  // 단수 관용형
  if (digit === '1' && unit === 'hour') {
    return 'an hour';
  }

  if (digit === '1' && unit === 'month') {
    return 'a month';
  }

  // 1~10은 일반 문장에서 단어 표기가 더 자연스럽습니다.
  // 11 이상은 30 minutes처럼 숫자 표기를 유지합니다.
  const smallNumberMap:
    Readonly<Record<string, string>> = {
      '1': 'one',
      '2': 'two',
      '3': 'three',
      '4': 'four',
      '5': 'five',
      '6': 'six',
      '7': 'seven',
      '8': 'eight',
      '9': 'nine',
      '10': 'ten',
    };

  const nativeNumberMap:
    Readonly<Record<string, string>> = {
      '한': 'one',
      '하나': 'one',
      '두': 'two',
      '둘': 'two',
      '세': 'three',
      '셋': 'three',
      '네': 'four',
      '넷': 'four',
      '다섯': 'five',
      '여섯': 'six',
      '일곱': 'seven',
      '여덟': 'eight',
      '아홉': 'nine',
      '열': 'ten',
    };

  const numberWord =
    nativeNumberMap[sourceNumber] ||
    smallNumberMap[digit] ||
    digit;

  return `${numberWord} ${unit}${
    digit === '1'
      ? ''
      : 's'
  }`;
};

const twoProNormalizeKoreanVerb = (value: string): string[] => {
  const cleanValue = twoProCleanCapturedKo(value).replace(/\s+/g, '_');
  const candidates = new Set<string>();

  const add = (candidate: string) => {
    const cleanCandidate = candidate.replace(/^_+|_+$/g, '').trim();
    if (cleanCandidate) candidates.add(cleanCandidate);
  };

  add(cleanValue);

  if (!cleanValue.endsWith('다')) {
    add(`${cleanValue}다`);
  }

  if (!cleanValue.endsWith('하다')) {
    add(`${cleanValue}하다`);
  }

  const endingRules: Array<[RegExp, string]> = [
    [/하는$/, '하다'],
    [/하기$/, '하다'],
    [/하며$/, '하다'],
    [/해서$/, '하다'],
    [/하여$/, '하다'],
    [/해$/, '하다'],
    [/하고$/, '하다'],
    [/했다$/, '하다'],
    [/합니다$/, '하다'],
    [/해요$/, '하다'],
    [/할$/, '하다'],
    [/을$/, '다'],
    [/ㄹ$/, '다'],
  ];

  for (const [pattern, replacement] of endingRules) {
    if (pattern.test(cleanValue)) {
      add(cleanValue.replace(pattern, replacement));
    }
  }

  return [...candidates];
};

// ============================================================================
// ☆ TwoPro v5.6: [V] 슬롯에 잡힌 어간을 사전 표제어 기본형으로 복원합니다.
// 예: 예약 → 예약하다, 검토 → 검토하다, 보내 → 보내다, 여 → 열다
// ============================================================================
const TWO_PRO_KO_EN_VERB_CAPTURE_OVERRIDES_V56: Record<string, string> = {
  '예약': '예약하다',
  '예약하': '예약하다',
  '확인': '확인하다',
  '확인하': '확인하다',
  '검토': '검토하다',
  '검토하': '검토하다',
  '보내': '보내다',
  '보내기': '보내다',
  '여': '열다',
  '열': '열다',
  '열기': '열다',
  '사용': '사용하다',
  '사용하': '사용하다',
  '변경': '변경하다',
  '변경하': '변경하다',
  '번역': '번역하다',
  '번역하': '번역하다',
  '제출': '제출하다',
  '제출하': '제출하다',
  '취소': '취소하다',
  '취소하': '취소하다',
  '추천': '추천하다',
  '추천하': '추천하다',
};

const twoProCanonicalKoreanVerbV56 = (
  value: string
): string => {
  const cleanValue = twoProCleanCapturedKo(value)
    .replace(/\s+/g, '')
    .trim();

  if (!cleanValue) {
    return cleanValue;
  }

  if (TWO_PRO_KO_EN_VERB_CAPTURE_OVERRIDES_V56[cleanValue]) {
    return TWO_PRO_KO_EN_VERB_CAPTURE_OVERRIDES_V56[cleanValue];
  }

  const candidates = twoProNormalizeKoreanVerb(cleanValue);

  for (const candidate of candidates) {
    if (
      TWO_PRO_KO_EN_COMMON_VERBS[candidate] ||
      TWO_PRO_KO_EN_LEXICAL_PRIORITIES_V5[candidate]
    ) {
      return candidate;
    }
  }

  if (/하$/.test(cleanValue)) {
    return `${cleanValue}다`;
  }

  if (/^[가-힣]+$/.test(cleanValue) && !cleanValue.endsWith('다')) {
    return `${cleanValue}다`;
  }

  return cleanValue;
};

const twoProCleanEnglishCandidate = (value: string): string => {
  let candidate = String(value || '')
    .replace(/\([^)]*\)/g, ' ')
    .replace(/\[[^\]]*\]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  candidate = candidate
    .split(/\s*(?:,|;|\/|\||=|:|：)\s*/)[0]
    .trim();

  candidate = candidate
    .replace(/^[\-–—]+\s*|\s*[\-–—]+$/g, '')
    .replace(/[.?!]+$/g, '')
    .trim();

  return candidate;
};

const twoProExtractEnglishCandidates = (
  lineText: string,
  koreanTerm: string
): string[] => {
  const line = String(lineText || '').normalize('NFC').trim();
  const term = String(koreanTerm || '').normalize('NFC').trim();

  if (!line || !term || !line.includes(term)) {
    return [];
  }

  const escapedTerm = twoProEscapeRegex(term);
  const candidates: string[] = [];

  const koreanFirst = line.match(
    new RegExp(
      `^\\s*${escapedTerm}(?:\\s*[:：=\\t\\-–—]\\s*|\\s+)(.+)$`,
      'i'
    )
  );

  if (koreanFirst?.[1]) {
    candidates.push(koreanFirst[1]);
  }

  const englishFirst = line.match(
    new RegExp(
      `^(.+?)(?:\\s*[:：=\\t\\-–—]\\s*|\\s+)${escapedTerm}(?:\\s|$)`,
      'i'
    )
  );

  if (englishFirst?.[1]) {
    candidates.push(englishFirst[1]);
  }

  const termIndex = line.indexOf(term);

  if (termIndex > 0) {
    candidates.push(line.slice(0, termIndex));
  }

  const afterTerm = line.slice(termIndex + term.length);

  if (afterTerm.trim()) {
    candidates.push(afterTerm);
  }

  return [...new Set(
    candidates
      .map(twoProCleanEnglishCandidate)
      .filter((candidate) => {
        if (!candidate || !/[A-Za-z]/.test(candidate)) {
          return false;
        }

        if (/[가-힣]/.test(candidate)) {
          return false;
        }

        return candidate.split(/\s+/).length <= 6;
      })
  )];
};

// ============================================================================
// ☆ TwoPro v5.4: 기본영어 1:1 정확 표제어 후보 추출
// "서울 Seoul", "Seoul : 서울"처럼 한쪽 전체가 한국어 표제어와 정확히
// 일치하는 줄만 참고 단어 후보로 사용합니다. "서울시", "호텔 경영자"처럼
// 부분 문자열만 겹치는 줄은 제외합니다.
// ============================================================================
const twoProExtractExactBilingualCandidatesV54 = (
  lineText: string,
  koreanTerm: string
): string[] => {
  const line = String(lineText || '')
    .normalize('NFC')
    .replace(/\s+/g, ' ')
    .trim();

  const term = String(koreanTerm || '')
    .normalize('NFC')
    .replace(/\s+/g, ' ')
    .trim();

  if (!line || !term) {
    return [];
  }

  const escapedTerm = twoProEscapeRegex(term);
  const rawCandidates: string[] = [];

  const separatedPatterns = [
    new RegExp(`^${escapedTerm}\\s*(?:[:：=\\t]|[-–—]\\s+)\\s*(.+)$`, 'i'),
    new RegExp(`^(.+?)\\s*(?:[:：=\\t]|\\s+[-–—])\\s*${escapedTerm}$`, 'i'),
  ];

  for (const pattern of separatedPatterns) {
    const match = line.match(pattern);
    if (match?.[1]) {
      rawCandidates.push(match[1]);
    }
  }

  // 구분기호 없이 "한국어 영어" 또는 "영어 한국어"인 짧은 1:1 행도 허용합니다.
  const koreanFirst = line.match(
    new RegExp(`^${escapedTerm}\\s+([A-Za-z][A-Za-z'’.-]*(?:\\s+[A-Za-z][A-Za-z'’.-]*){0,3})$`, 'i')
  );
  if (koreanFirst?.[1]) {
    rawCandidates.push(koreanFirst[1]);
  }

  const englishFirst = line.match(
    new RegExp(`^([A-Za-z][A-Za-z'’.-]*(?:\\s+[A-Za-z][A-Za-z'’.-]*){0,3})\\s+${escapedTerm}$`, 'i')
  );
  if (englishFirst?.[1]) {
    rawCandidates.push(englishFirst[1]);
  }

  return [...new Set(
    rawCandidates
      .map(twoProNormalizeEnglishCandidateV5)
      .filter((candidate) => {
        if (!candidate || !/^[A-Za-z][A-Za-z'’.-]*(?:\s+[A-Za-z][A-Za-z'’.-]*){0,3}$/.test(candidate)) {
          return false;
        }

        // 쉼표·세미콜론·슬래시가 있는 나열형 정의는 1:1 대응어가 아닙니다.
        if (/[,;/|]/.test(candidate)) {
          return false;
        }

        return true;
      })
  )];
};

const twoProScoreEnglishCandidate = (
  candidate: string,
  lineText: string,
  koreanTerm: string,
  slotType: string,
  sourceOrder: number
): number => {
  const wordCount = candidate.split(/\s+/).filter(Boolean).length;
  const lowerCandidate = candidate.toLowerCase();
  let score = 0;

  const compactLine = String(lineText || '')
    .replace(/\s+/g, ' ')
    .trim();

  if (
    compactLine === `${candidate} ${koreanTerm}` ||
    compactLine === `${koreanTerm} ${candidate}` ||
    compactLine === `${candidate}: ${koreanTerm}` ||
    compactLine === `${koreanTerm}: ${candidate}`
  ) {
    score += 120;
  }

  if (wordCount === 1) score += 45;
  else if (wordCount === 2) score += 25;
  else score -= wordCount * 5;

  if (/^[A-Za-z][A-Za-z'-]*$/.test(candidate)) {
    score += 20;
  }

  if (slotType === 'V') {
    if (/^to\s+/i.test(candidate)) score += 15;
    if (/ing$/i.test(candidate)) score -= 8;
  } else {
    if (/^to\s+/i.test(candidate)) score -= 35;
    if (/\b(?:do|does|did|is|are|was|were|have|has|had)\b/i.test(candidate)) {
      score -= 25;
    }
  }

  if (slotType === 'PLACE' && /^[A-Z]/.test(candidate)) {
    score += 12;
  }

  if (lowerCandidate === koreanTerm.toLowerCase()) {
    score -= 100;
  }

  score -= Math.min(Number(sourceOrder || 0), 100000) / 100000;

  return score;
};

const twoProLookupBasicEnglish = async (
  koreanTerm: string,
  slotType: string,
  supabase: any
): Promise<string | null> => {
  const cleanTerm = twoProCleanCapturedKo(koreanTerm);

  if (!cleanTerm || !supabase) {
    return null;
  }

  const cacheKey = `${slotType}::${cleanTerm}`;

  if (TWO_PRO_KO_EN_SLOT_CACHE.has(cacheKey)) {
    return TWO_PRO_KO_EN_SLOT_CACHE.get(cacheKey) || null;
  }

  try {
    const escapedSearchTerm = cleanTerm
      .replace(/\\/g, '\\\\')
      .replace(/%/g, '\\%')
      .replace(/_/g, '\\_');

    const { data, error } = await supabase
      .from('dictionary_lines')
      .select('line_text, source_order, category_id')
      .eq('category_id', 1)
      .ilike('line_text', `%${escapedSearchTerm}%`)
      .order('source_order', { ascending: true })
      .limit(80);

    if (error) {
      console.error('[한영 슬롯 기본영어 조회 오류]', {
        koreanTerm: cleanTerm,
        slotType,
        message: error.message,
      });

      TWO_PRO_KO_EN_SLOT_CACHE.set(cacheKey, null);
      return null;
    }

    const ranked: Array<{
      candidate: string;
      score: number;
    }> = [];

    for (const item of Array.isArray(data) ? data : []) {
      const lineText = String(item?.line_text || '');

      for (const candidate of twoProExtractEnglishCandidates(
        lineText,
        cleanTerm
      )) {
        ranked.push({
          candidate,
          score: twoProScoreEnglishCandidate(
            candidate,
            lineText,
            cleanTerm,
            slotType,
            Number(item?.source_order || 0)
          ),
        });
      }
    }

    ranked.sort((a, b) => b.score - a.score);

    const bestCandidate = ranked[0]?.candidate || null;

    TWO_PRO_KO_EN_SLOT_CACHE.set(cacheKey, bestCandidate);

    return bestCandidate;
  } catch (error) {
    console.error('[한영 슬롯 기본영어 조회 예외]', {
      koreanTerm: cleanTerm,
      slotType,
      error,
    });

    TWO_PRO_KO_EN_SLOT_CACHE.set(cacheKey, null);
    return null;
  }
};

// ============================================================================
// ☆ TwoPro v9.21-safe: PHRASES의 슬롯 사용 안전성 판정
//
// PHRASES는 단독 구 번역과 참고 표현에는 모두 사용할 수 있지만,
// 조사·시제·주어 변화가 포함된 표현을 임의의 [N]/[PLACE] 슬롯에 넣으면
// in/to/from, want/wants/wanted 등이 잘못 고정될 수 있습니다.
//
// 따라서:
// - 순수 명사구는 [N] 슬롯에 사용
// - 시간구는 [TIME]/[DURATION] 슬롯에 사용
// - 조사 포함 장소구·완성 서술구는 단독 번역/참고 표현에만 사용
// ============================================================================
const TWO_PRO_PHRASE_TEMPORAL_ENGLISH_V921 =
  /^(?:every\b|last\b|next\b|until\b|during\b|from\b.+\b(?:to|till|until)\b|in the future\b|today\b|tomorrow\b|yesterday\b|tonight\b)/i;

const twoProCanUseExactPhraseForSlotV921 = (
  entry: TwoProPhraseEntryV915,
  slotType: string
): boolean => {
  const ko = String(entry?.ko || '')
    .normalize('NFC')
    .replace(/\s+/g, ' ')
    .trim();

  const en = twoProEmbeddedPhraseEnglishV915(
    entry?.en || ''
  );

  if (!ko || !en) {
    return false;
  }

  if (
    slotType === 'TIME' ||
    slotType === 'DURATION' ||
    slotType === 'DAY'
  ) {
    return TWO_PRO_PHRASE_TEMPORAL_ENGLISH_V921.test(
      en
    );
  }

  if (slotType === 'N') {
    // 순수 명사구만 허용합니다.
    // 조사·종결어미·명령형·시제 표현은 슬롯에 넣지 않습니다.
    return !(
      /(?:에서|에게|으로|로|까지|부터|위하여|에)$/u.test(
        ko
      ) ||
      /(?:한다|했다|원한다|원했다|싶습니다|싶어요|주세요|갔다|쉽다)$/u.test(
        ko
      )
    );
  }

  // PLACE는 전치사를 영어 템플릿과 동사가 결정해야 하므로
  // 조사까지 포함된 PHRASES를 직접 주입하지 않습니다.
  if (
    slotType === 'PLACE' ||
    slotType === 'IO' ||
    slotType === 'V' ||
    slotType === 'S' ||
    slotType === 'SUBJ' ||
    slotType === 'ADJ'
  ) {
    return false;
  }

  return false;
};

const twoProTranslateKoEnSlot = async (
  token: string,
  capturedValue: string,
  supabase: any
): Promise<string | null> => {
  const slotType = twoProBaseSlotType(token);
  const cleanValue = twoProCleanCapturedKo(capturedValue);

  if (!cleanValue) {
    return null;
  }

  // ☆ TwoPro v9.15: 슬롯에 캡처된 값이 phrases JSON의 구와 정확히 같으면
  // 개별 단어 DB 조회보다 먼저 구 전체 번역을 사용합니다.
  const exactPhraseForSlotV915 =
    twoProFindExactPhraseV915(cleanValue);

  if (
    exactPhraseForSlotV915 &&
    twoProCanUseExactPhraseForSlotV921(
      exactPhraseForSlotV915,
      slotType
    )
  ) {
    const embeddedPhraseEnglish =
      twoProEmbeddedPhraseEnglishV915(
        exactPhraseForSlotV915.en
      );

    // v9.21:
    // 이 함수의 반환형은 string입니다.
    // 객체를 반환하면 영어 템플릿에서 [object Object]가 됩니다.
    return embeddedPhraseEnglish;
  }

  if (/^[A-Za-z0-9][A-Za-z0-9\s'’\-]*$/.test(cleanValue)) {
    return cleanValue;
  }

  if (slotType === 'S') {
    if (TWO_PRO_KO_EN_SUBJECTS[cleanValue]) {
      return TWO_PRO_KO_EN_SUBJECTS[cleanValue];
    }

    return (
      TWO_PRO_KO_EN_COMMON_NOUNS[cleanValue] ||
      await twoProLookupBasicEnglish(cleanValue, 'N', supabase)
    );
  }

  // ☆ TwoPro v9.29:
  // rules-ko-en.json의 구형 문자열 슬롯도
  // one day / three days / an hour 표기를 사용합니다.
  if (slotType === 'DURATION' || slotType === 'TIME') {
    const duration = twoProTranslateDuration(cleanValue);

    if (duration) {
      return duration;
    }
  }

  if (slotType === 'PLACE') {
    return (
      TWO_PRO_KO_EN_PLACES[cleanValue] ||
      TWO_PRO_KO_EN_COMMON_NOUNS[cleanValue] ||
      await twoProLookupBasicEnglish(cleanValue, 'PLACE', supabase)
    );
  }

  if (slotType === 'V') {
    for (const verbCandidate of twoProNormalizeKoreanVerb(cleanValue)) {
      if (TWO_PRO_KO_EN_COMMON_VERBS[verbCandidate]) {
        return TWO_PRO_KO_EN_COMMON_VERBS[verbCandidate];
      }

      if (MOCK_XDIC_DB[verbCandidate]) {
        return String(MOCK_XDIC_DB[verbCandidate])
          .replace(/^to\s+/i, '')
          .trim();
      }
    }

    const dbVerb = await twoProLookupBasicEnglish(
      cleanValue,
      'V',
      supabase
    );

    return dbVerb
      ? dbVerb.replace(/^to\s+/i, '').trim()
      : null;
  }

  if (slotType === 'NUM') {
    return twoProKoreanNumberToDigit(cleanValue) || cleanValue;
  }

  if (slotType === 'DAY') {
    const dayMap: Record<string, string> = {
      '월요일': 'Monday',
      '화요일': 'Tuesday',
      '수요일': 'Wednesday',
      '목요일': 'Thursday',
      '금요일': 'Friday',
      '토요일': 'Saturday',
      '일요일': 'Sunday',
      '오늘': 'today',
      '내일': 'tomorrow',
      '어제': 'yesterday',
    };

    if (dayMap[cleanValue]) {
      return dayMap[cleanValue];
    }
  }

  if (
    slotType === 'N' ||
    TWO_PRO_KO_EN_NOUN_SLOT_TYPES.has(slotType)
  ) {
    return (
      TWO_PRO_KO_EN_COMMON_NOUNS[cleanValue] ||
      await twoProLookupBasicEnglish(cleanValue, 'N', supabase)
    );
  }

  if (MOCK_XDIC_DB[cleanValue]) {
    return String(MOCK_XDIC_DB[cleanValue]);
  }

  return (
    TWO_PRO_KO_EN_COMMON_NOUNS[cleanValue] ||
    await twoProLookupBasicEnglish(cleanValue, slotType, supabase)
  );
};

const twoProStartsWithVowelSound = (word: string): boolean => {
  const cleanWord = String(word || '')
    .replace(/^[^A-Za-z0-9]+/, '')
    .toLowerCase();

  if (!cleanWord) {
    return false;
  }

  if (/^(hour|honest|honor|honour|heir|herb)\b/.test(cleanWord)) {
    return true;
  }

  if (/^(uni(?:versity|form|t)|user|use|usual|one|once|euro)\b/.test(cleanWord)) {
    return false;
  }

  if (/^[8]/.test(cleanWord)) {
    return true;
  }

  return /^[aeiou]/.test(cleanWord);
};

const twoProFixEnglishArticles = (value: string): string => {
  let text = String(value || '');

  text = text.replace(
    /\b(a\/an|a|an)\s+(the\s+)?([A-Za-z0-9][A-Za-z0-9'’\-]*)/gi,
    (
      matchedText: string,
      _article: string,
      existingThe: string | undefined,
      firstWord: string,
      offset: number,
      wholeText: string
    ) => {
      if (existingThe) {
        return `the ${firstWord}`;
      }

      const lowerWord = String(firstWord).toLowerCase();

      // v9.19:
      // 관사 뒤의 첫 단어만 보고 복수 명사로 단정하면
      // a famous doctor의 famous가 s로 끝난다는 이유로
      // 관사가 제거되는 문제가 있었습니다.
      //
      // 뒤에 다른 영어 단어가 이어지면 첫 단어는 형용사 또는
      // 명사 수식어일 수 있으므로 관사를 유지합니다.
      const remainingText = String(wholeText || '')
        .slice(offset + matchedText.length);

      const hasFollowingLexicalWord =
        /^\s+[A-Za-z0-9][A-Za-z0-9'’\-]*/.test(
          remainingText
        );

      if (
        !hasFollowingLexicalWord &&
        (
          TWO_PRO_KO_EN_UNCOUNTABLE_NOUNS.has(
            lowerWord
          ) ||
          (
            /s$/i.test(firstWord) &&
            !/ss$/i.test(firstWord)
          )
        )
      ) {
        return firstWord;
      }

      return `${
        twoProStartsWithVowelSound(firstWord)
          ? 'an'
          : 'a'
      } ${firstWord}`;
    }
  );

  text = text
    .replace(/\bthe\s+the\b/gi, 'the')
    .replace(/\b(?:a|an)\s+(the\s+)/gi, '$1');

  const noArticleTerms = [
    'English',
    'Korean',
    'Japanese',
    'Chinese',
    'French',
    'German',
    'Monday',
    'Tuesday',
    'Wednesday',
    'Thursday',
    'Friday',
    'Saturday',
    'Sunday',
    'PDF',
    'HTML',
    'XML',
    'CSV',
    'JSON',
  ];

  for (const term of noArticleTerms) {
    const escapedTerm = term.replace(
      /[.*+?^${}()|[\]\\]/g,
      '\\$&'
    );

    text = text.replace(
      new RegExp(
        `\\b(?:the|a|an)\\s+${escapedTerm}\\b`,
        'gi'
      ),
      term
    );
  }

  const properPlaces = [
    'Seoul',
    'Busan',
    'Daegu',
    'Incheon',
    'Korea',
    'Japan',
    'China',
    'France',
    'Germany',
  ];

  for (const place of properPlaces) {
    text = text.replace(
      new RegExp(`\\bthe\\s+${place}\\b`, 'g'),
      place
    );
  }

  return text;
};

// ============================================================================
// ☆ TwoPro v9.7-safe: 영어 언어명·고유 표기 정규화
//
// 사전·DB·JSON 규칙에 english처럼 소문자로 저장되어 있어도 언어명은
// 문장 내부 위치와 관계없이 English처럼 표준 대문자로 표시합니다.
// 문장 첫 글자 대문자 보정과 별개인 공통 최종 출력 계층입니다.
// ============================================================================
const TWO_PRO_ENGLISH_LANGUAGE_NAMES_V97: Readonly<
  Record<string, string>
> = {
  english: 'English',
  korean: 'Korean',
  japanese: 'Japanese',
  chinese: 'Chinese',
  french: 'French',
  german: 'German',
  spanish: 'Spanish',
  italian: 'Italian',
  russian: 'Russian',
  arabic: 'Arabic',
  portuguese: 'Portuguese',
};

// ☆ TwoPro v9.43-safe: 영어 인명은 문장 중간에서도 고유명사 대문자를 유지합니다.
// 현재 회귀 테스트에서 실제로 확인된 Betty만 제한적으로 등록합니다.
const TWO_PRO_ENGLISH_PROPER_NAMES_V943: Readonly<
  Record<string, string>
> = {
  betty: 'Betty',
};

const twoProNormalizeEnglishProperWordsV97 = (
  value: string
): string => {
  let text = String(value || '');

  for (const [lowerWord, canonicalWord] of Object.entries(
    TWO_PRO_ENGLISH_LANGUAGE_NAMES_V97
  )) {
    text = text.replace(
      new RegExp(`\\b${lowerWord}\\b`, 'gi'),
      canonicalWord
    );
  }

  for (const [lowerWord, canonicalWord] of Object.entries(
    TWO_PRO_ENGLISH_PROPER_NAMES_V943
  )) {
    text = text.replace(
      new RegExp(`\\b${lowerWord}\\b`, 'gi'),
      canonicalWord
    );
  }

  // 영어 1인칭 대명사 i는 문장 중간에서도 항상 대문자입니다.
  text = text.replace(/\bi\b/g, 'I');

  return text;
};

const twoProFinalizeEnglish = (
  value: string,
  sourceText: string
): string => {
  let text = twoProNormalizeEnglishProperWordsV97(
    twoProFixEnglishArticles(value)
  )
    .replace(/\s+/g, ' ')
    .replace(/\s+([?.!,;:])/g, '$1')
    .trim();

  if (!text) {
    return text;
  }

  text = text.replace(
    /^([a-z])/,
    (match) => match.toUpperCase()
  );

  if (!/[.?!]$/.test(text)) {
    const sourceForPunctuation =
      String(sourceText || '').trim();

    const sourceWithoutTerminalPeriod =
      sourceForPunctuation
        .replace(/[.!]+$/g, '')
        .trim();

    const sourceLastToken =
      sourceWithoutTerminalPeriod
        .split(/\s+/)
        .filter(Boolean)
        .pop() || '';

    // ☆ TwoPro v11.33-safe:
    // '-나요'는 의문 종결어미이기도 하지만, 일어나다/끝나다/태어나다처럼
    // 어간 자체가 '나'로 끝나는 동사의 해요체와 표면형이 겹칩니다.
    // 기존 정규식은 '일어나요'를 무조건 질문으로 보아
    // 평서문도 'She gets up?'으로 끝나는 회귀를 만들었습니다.
    // 명시적 ?는 항상 질문으로 보존하고, ?가 없는 '-나요'는
    // 활용 사전에 실제 평서 해요체로 등록된 완전한 마지막 토큰이면
    // 평서문으로 우선 판정합니다.
    // ☆ TwoPro v11.44-safe:
    // '네모나요'처럼 형용사/상태표현의 평서 해요체도 '-나요'로 끝날 수 있습니다.
    // v11.33은 동사 활용 사전(conjugationDB)만 확인했기 때문에
    // '이 상자는 네모나요'를 질문으로 오인했습니다.
    // 명시적 '?'가 없는 경우, 동사 활용 사전 또는 검증된 형용사 활용표에
    // 정확히 등록된 표면형이면 평서문으로 우선 판정합니다.
    const isKnownDeclarativeNayoSurfaceV1133 =
      /나요$/u.test(sourceLastToken) &&
      (
        Object.prototype.hasOwnProperty.call(
          conjugationDB,
          sourceLastToken
        ) ||
        Object.prototype.hasOwnProperty.call(
          TWO_PRO_KO_EN_ADJECTIVE_FORM_MAP_V5,
          sourceLastToken
        )
      );

    const sourceIsQuestion =
      /\?$/.test(sourceForPunctuation) ||
      /(습니까|까요|인가요|건가요|니|냐)\s*$/.test(
        sourceWithoutTerminalPeriod
      ) ||
      (
        /나요\s*$/.test(sourceWithoutTerminalPeriod) &&
        !isKnownDeclarativeNayoSurfaceV1133
      );

    text += sourceIsQuestion ? '?' : '.';
  }

  return text;
};


// ============================================================================
// ☆ TwoPro v9.84-safe: common verbs 한국어 SAFE exact loader
//
// - rules-common-verbs.json의 SAFE 한국어 대표형만 양방향에 사용합니다.
// - PHRASES와 rules JSON exact가 우선하며, 이 인덱스는 그 다음 단계에서만 사용합니다.
// - 한국어 전체 입력이 대표형/안전한 현재·과거·미래 표면형과 정확히 같을 때만 매치합니다.
// - 문장 내부를 전역 치환하지 않습니다.
// ============================================================================
type TwoProCommonVerbKoEnTenseV984 =
  | 'present'
  | 'past'
  | 'future';

type TwoProCommonVerbKoEnHitV984 = {
  sourceSurface: string;
  tense: TwoProCommonVerbKoEnTenseV984;
  entry: any;
};

const TWO_PRO_COMMON_KO_SURFACE_INDEX_V984 =
  new Map<
    string,
    TwoProCommonVerbKoEnHitV984
  >();

const TWO_PRO_COMMON_KO_AMBIGUOUS_SURFACES_V984 =
  new Set<string>();

const TWO_PRO_COMMON_PLAIN_KO_CONJUGATION_V984:
  Record<string, readonly [string, string]> = {};

String(KO_ENDINGS_RAW || '')
  .split('|')
  .forEach((item) => {
    const [
      present,
      past,
      future,
    ] = item.split(':');

    if (
      present &&
      past &&
      future
    ) {
      TWO_PRO_COMMON_PLAIN_KO_CONJUGATION_V984[
        present
      ] = [past, future];
    }
  });

const TWO_PRO_COMMON_PLAIN_SIGNATURE_INDEX_V984 =
  new Map<string, string[]>();

for (
  const [
    present,
    pair,
  ] of Object.entries(
    TWO_PRO_COMMON_PLAIN_KO_CONJUGATION_V984
  )
) {
  const signature =
    `${pair[0]}\u0000${pair[1]}`;

  const bucket =
    TWO_PRO_COMMON_PLAIN_SIGNATURE_INDEX_V984.get(
      signature
    ) || [];

  bucket.push(present);

  TWO_PRO_COMMON_PLAIN_SIGNATURE_INDEX_V984.set(
    signature,
    bucket
  );
}

const twoProAddCommonKoSurfaceV984 = (
  surfaceValue: unknown,
  tense: TwoProCommonVerbKoEnTenseV984,
  entry: any
) => {
  const surface =
    twoProNormalizeKoreanCommonVerbSurfaceV1(
      surfaceValue
    );

  if (!surface) {
    return;
  }

  const existing =
    TWO_PRO_COMMON_KO_SURFACE_INDEX_V984.get(
      surface
    );

  if (
    existing &&
    existing.entry?.lemma !== entry?.lemma
  ) {
    TWO_PRO_COMMON_KO_AMBIGUOUS_SURFACES_V984.add(
      surface
    );
    TWO_PRO_COMMON_KO_SURFACE_INDEX_V984.delete(
      surface
    );
    return;
  }

  if (
    TWO_PRO_COMMON_KO_AMBIGUOUS_SURFACES_V984.has(
      surface
    )
  ) {
    return;
  }

  // 같은 lemma의 동일 surface가 여러 시제로 겹치면
  // 문맥 없는 단독 검색에서는 present를 우선합니다.
  if (existing) {
    if (
      existing.tense !== 'present' &&
      tense === 'present'
    ) {
      TWO_PRO_COMMON_KO_SURFACE_INDEX_V984.set(
        surface,
        {
          sourceSurface: surface,
          tense,
          entry,
        }
      );
    }
    return;
  }

  TWO_PRO_COMMON_KO_SURFACE_INDEX_V984.set(
    surface,
    {
      sourceSurface: surface,
      tense,
      entry,
    }
  );
};

for (
  const entry of
  TWO_PRO_COMMON_SAFE_VERB_ENTRIES_V1
) {
  const koLemma = String(
    entry.ko || ''
  ).trim();

  if (!koLemma) {
    continue;
  }

  twoProAddCommonKoSurfaceV984(
    koLemma,
    'present',
    entry
  );

  const plainPair =
    TWO_PRO_COMMON_PLAIN_KO_CONJUGATION_V984[
      koLemma
    ];

  if (plainPair) {
    const [
      plainPast,
      plainFuture,
    ] = plainPair;

    twoProAddCommonKoSurfaceV984(
      plainPast,
      'past',
      entry
    );

    twoProAddCommonKoSurfaceV984(
      plainFuture,
      'future',
      entry
    );

    const signature =
      `${plainPast}\u0000${plainFuture}`;

    for (
      const presentVariant of
      TWO_PRO_COMMON_PLAIN_SIGNATURE_INDEX_V984.get(
        signature
      ) || []
    ) {
      if (
        !/[?？]$/u.test(
          presentVariant
        )
      ) {
        twoProAddCommonKoSurfaceV984(
          presentVariant,
          'present',
          entry
        );
      }
    }
  }

  const mappedPast =
    getKoreanConjugation(
      koLemma,
      'past'
    );

  if (
    mappedPast &&
    mappedPast !== koLemma
  ) {
    twoProAddCommonKoSurfaceV984(
      mappedPast,
      'past',
      entry
    );

    if (mappedPast.endsWith('습니다')) {
      twoProAddCommonKoSurfaceV984(
        mappedPast.replace(
          /습니다$/u,
          '다'
        ),
        'past',
        entry
      );
    }
  }

  const mappedFuture =
    getKoreanConjugation(
      koLemma,
      'future'
    );

  if (
    mappedFuture &&
    mappedFuture !== koLemma
  ) {
    twoProAddCommonKoSurfaceV984(
      mappedFuture,
      'future',
      entry
    );

    if (
      mappedFuture.endsWith('겠습니다')
    ) {
      twoProAddCommonKoSurfaceV984(
        mappedFuture.replace(
          /겠습니다$/u,
          '겠다'
        ),
        'future',
        entry
      );
    }
  }

  // -하다 활용은 생산성이 매우 높아 누락된 SAFE 항목도 최소 보완합니다.
  if (koLemma.endsWith('하다')) {
    const stem =
      koLemma.slice(
        0,
        -'하다'.length
      );

    twoProAddCommonKoSurfaceV984(
      `${stem}한다`,
      'present',
      entry
    );

    twoProAddCommonKoSurfaceV984(
      `${stem}했다`,
      'past',
      entry
    );

    twoProAddCommonKoSurfaceV984(
      `${stem}하겠다`,
      'future',
      entry
    );
  }
}

const twoProTryCommonVerbExactKoEnV984 = (
  value: unknown
): TwoProCommonVerbKoEnHitV984 | null => {
  const surface =
    twoProNormalizeKoreanCommonVerbSurfaceV1(
      value
    );

  if (!surface) {
    return null;
  }

  return (
    TWO_PRO_COMMON_KO_SURFACE_INDEX_V984.get(
      surface
    ) || null
  );
};

const twoProRenderCommonVerbEnglishV984 = (
  hit: TwoProCommonVerbKoEnHitV984
): string | null => {
  const lemma =
    String(
      hit.entry?.lemma || ''
    ).trim();

  if (!lemma) {
    return null;
  }

  if (hit.tense === 'past') {
    const past =
      hit.entry?.forms?.past?.[0];

    return past
      ? String(past).trim()
      : null;
  }

  if (hit.tense === 'future') {
    return `will ${lemma}`;
  }

  return lemma;
};


// ============================================================================
// ☆ TwoPro v9.85-safe: common adjectives 한국어 SAFE exact loader
