const twoProAnalyzePredicateV52 = (
  value: string
): TwoProKoEnPredicateInfoV52 | null => {
  const cleanValue =
    twoProCleanPredicateFormV52(value);

  const indexed =
    TWO_PRO_KO_EN_PREDICATE_FORM_INDEX_V52.get(
      cleanValue
    );

  if (indexed) {
    return {
      base: indexed.base,
      tense: indexed.tense,
    };
  }

  // ☆ TwoPro v8.3:
  // 해체·해요체·하십시오체의 -하다 활용을 한 번에 기본형으로 복원합니다.
  // 공부했다 → 공부하다, 일했다 → 일하다, 운동했어요 → 운동하다
  if (/(?:하겠습니다|하겠다)$/u.test(cleanValue)) {
    return {
      base: cleanValue.replace(
        /(?:하겠습니다|하겠다)$/u,
        '하다'
      ),
      tense: 'future',
    };
  }

  if (
    /(?:했습니다|하였습니다|했다|하였다)$/u.test(
      cleanValue
    )
  ) {
    return {
      base: cleanValue.replace(
        /(?:했습니다|하였습니다|했다|하였다)$/u,
        '하다'
      ),
      tense: 'past',
    };
  }

  if (/(?:합니다|한다|해요)$/u.test(cleanValue)) {
    return {
      base: cleanValue.replace(
        /(?:합니다|한다|해요)$/u,
        '하다'
      ),
      tense: 'present',
    };
  }

  return null;
};

const twoProTranslateSubjectV52 = async (
  source: string,
  supabase: any
): Promise<TwoProKoEnCandidateBundleV5 | null> => {
  const cleanSource =
    twoProNormalizeKoreanNounV5(source);

  const pronoun =
    TWO_PRO_KO_EN_SUBJECTS[cleanSource];

  if (pronoun) {
    return {
      source: cleanSource,
      selected: pronoun,
      candidates: [pronoun],
      confidence: 1,
      slotType: 'S',
    };
  }

  const personName =
    TWO_PRO_KO_EN_PERSON_NAMES_V52[cleanSource];

  if (personName) {
    return {
      source: cleanSource,
      selected: personName,
      candidates: [personName],
      confidence: 1,
      slotType: 'S',
    };
  }

  return twoProLookupBasicEnglishCandidatesV5(
    cleanSource,
    'S',
    supabase
  );
};

