const twoProPlacePhraseV53 = (
  source: string,
  selected: string,
  particle: '에' | '에서',
  predicateBase: string
): string => {
  const cleanSource =
    twoProNormalizeKoreanNounV5(source);

  const cleanSelected = String(selected || '').trim();

  if (!cleanSelected) {
    return '';
  }

  const cityOrCountry = [
    '서울',
    '부산',
    '대구',
    '인천',
    '한국',
    '대한민국',
    '미국',
    '영국',
    '일본',
    '중국',
    '프랑스',
    '독일',
  ].includes(cleanSource);

  const stationaryFixed: Record<string, string> = {
    '학교': 'at school',
    '교회': 'at church',
    '집': 'at home',
    '호텔': 'at the hotel',
    '병원': 'at the hospital',
    '공항': 'at the airport',
    '회사': 'at the company',
    '사무실': 'at the office',
  };

  const destinationFixed: Record<string, string> = {
    '학교': 'to school',
    '교회': 'to church',
    '집': 'home',
    '호텔': 'to the hotel',
    '병원': 'to the hospital',
    '공항': 'to the airport',
    '회사': 'to the company',
    '사무실': 'to the office',
    // 층수는 사전의 upstairs/downstairs 후보보다 실제 층 서수를 우선합니다.
    '1층': 'to the first floor',
    '2층': 'to the second floor',
  };

  // ☆ TwoPro v5.8: '도착하다'는 to가 아니라 장소 유형에 따라 at/in을 사용합니다.
  if (particle === '에' && predicateBase === '도착하다') {
    if (cityOrCountry || /^[A-Z]/.test(cleanSelected)) {
      return `in ${cleanSelected}`;
    }

    if (/^(?:the\s+)/i.test(cleanSelected)) {
      return `at ${cleanSelected}`;
    }

    return `at the ${cleanSelected}`;
  }

  if (
    particle === '에서' &&
    TWO_PRO_KO_EN_SOURCE_MOVEMENT_VERBS_V53.has(
      predicateBase
    )
  ) {
    if (cityOrCountry || /^[A-Z]/.test(cleanSelected)) {
      return `from ${cleanSelected}`;
    }

    if (/^(?:the\s+)/i.test(cleanSelected)) {
      return `from ${cleanSelected}`;
    }

    return `from the ${cleanSelected}`;
  }

  // ☆ TwoPro v7.9-safe:
  // enter는 타동사이므로 실내 목적지 앞에 to를 붙이지 않습니다.
  // 방으로 들어갔다 → entered the room
  if (
    particle === '에' &&
    predicateBase === '들어가다' &&
    new Set([
      '방',
      '객실',
      '사무실',
      '교실',
      '건물',
    ]).has(cleanSource)
  ) {
    if (/^(?:the\s+)/i.test(cleanSelected)) {
      return cleanSelected;
    }

    return `the ${cleanSelected}`;
  }

  if (
    particle === '에' &&
    TWO_PRO_KO_EN_DESTINATION_MOVEMENT_VERBS_V53.has(
      predicateBase
    )
  ) {
    if (destinationFixed[cleanSource]) {
      return destinationFixed[cleanSource];
    }

    if (cityOrCountry || /^[A-Z]/.test(cleanSelected)) {
      return `to ${cleanSelected}`;
    }

    if (/^(?:the\s+)/i.test(cleanSelected)) {
      return `to ${cleanSelected}`;
    }

    return `to the ${cleanSelected}`;
  }

  if (stationaryFixed[cleanSource]) {
    return stationaryFixed[cleanSource];
  }

  if (cityOrCountry) {
    return `in ${cleanSelected}`;
  }

  if (/^(?:the\s+)/i.test(cleanSelected)) {
    return `in ${cleanSelected}`;
  }

  if (/^[A-Z]/.test(cleanSelected)) {
    return `in ${cleanSelected}`;
  }

  return `at the ${cleanSelected}`;
};

// ============================================================================
// ☆ TwoPro v5.9: 목적어 관사 문맥 보정
//
// 한국어의 무표지 단수 가산명사는 문맥상 a/an과 the가 모두 가능하지만,
// 문맥이 제공되지 않은 첫 언급에서는 a/an을 기본값으로 사용합니다.
// 따라서 '우산을 가져왔습니다'는 an umbrella가 되며,
// 특정 대상은 JSON 규칙이나 명시적 한정 표현에서 the를 유지합니다.
// ============================================================================
const twoProObjectPhraseV52 = (
  source: string,
  selected: string,
  predicateBase = ''
): string => {
  const rawSource = twoProCleanCapturedKo(source);
  const cleanSource =
    twoProNormalizeKoreanNounV5(source);

  const cleanSelected = String(selected || '').trim();

  if (!cleanSelected) {
    return '';
  }

  if (
    /^(?:a|an|the|some|my|your|his|her|our|their)\s+/i.test(
      cleanSelected
    )
  ) {
    return cleanSelected;
  }

  const isPlural =
    /들$/u.test(cleanSource) ||
    (/s$/i.test(cleanSelected) &&
      !/ss$/i.test(cleanSelected));

  if (
    isPlural ||
    TWO_PRO_KO_EN_UNCOUNTABLE_NOUNS.has(
      cleanSelected.toLowerCase()
    ) ||
    /^[A-Z]/.test(cleanSelected)
  ) {
    return cleanSelected;
  }

  // '그/이/저 + 명사'처럼 한정성이 명시되면 the를 사용합니다.
  if (/^(?:그|이|저)\s+/u.test(rawSource)) {
    return `the ${cleanSelected}`;
  }

  // ☆ TwoPro v7.9-safe:
  // 열다·닫다·잠그다의 목적어인 문은 대개 상황 속 특정 문이므로
  // a door보다 the door가 자연스럽습니다.
  if (
    cleanSource === '문' &&
    new Set([
      '열다',
      '닫다',
      '잠그다',
      '열어주다',
      '닫아주다',
    ]).has(predicateBase)
  ) {
    return 'the door';
  }

  // v5.5에서 이미 승인된 '가방을 가져오다 → the bag' 결과는
  // 회귀하지 않도록 호환 규칙으로 유지합니다.
  if (
    predicateBase === '가져오다' &&
    cleanSource === '가방'
  ) {
    return `the ${cleanSelected}`;
  }

  return `${
    twoProStartsWithVowelSound(cleanSelected)
      ? 'an'
      : 'a'
  } ${cleanSelected}`;
};

const TWO_PRO_ENGLISH_SMALL_CARDINALS_V928:
  Readonly<Record<string, string>> = {
    '1': 'one',
    '2': 'two',
    '3': 'three',
    '4': 'four',
    '5': 'five',
    '6': 'six',
    '7': 'seven',
    '8': 'eight',
    '9': 'nine',
    '10': 'ten',
  };

const TWO_PRO_KO_EN_NATIVE_NUMBER_WORDS_V54: Record<
  string,
  string
> = {
  '한': 'one',
  '하나': 'one',
  '두': 'two',
  '둘': 'two',
  '세': 'three',
  '셋': 'three',
  '네': 'four',
  '넷': 'four',
  '다섯': 'five',
  '여섯': 'six',
  '일곱': 'seven',
  '여덟': 'eight',
  '아홉': 'nine',
  '열': 'ten',
};

const twoProTranslateDurationNaturalV54 = (
  value: string
): string | null => {
  const cleanValue = twoProCleanCapturedKo(value)
    .replace(/\s*동안$/u, '')
    .trim();

  const match = cleanValue.match(
    /^(\d+|한|하나|두|둘|세|셋|네|넷|다섯|여섯|일곱|여덟|아홉|열)\s*(년|개월|달|주|일|시간|분)$/u
  );

  if (!match) {
    return twoProTranslateDuration(cleanValue);
  }

  const sourceNumber = match[1];
  const digit = twoProKoreanNumberToDigit(sourceNumber);

  if (!digit) {
    return null;
  }

  const unitMap: Record<string, string> = {
    '년': 'year',
    '개월': 'month',
    '달': 'month',
    '주': 'week',
    '일': 'day',
    '시간': 'hour',
    '분': 'minute',
  };

  const unit = unitMap[match[2]];
  if (!unit) {
    return null;
  }

  // v9.28:
  // 1일/3일처럼 작은 아라비아 숫자로 입력된 기간도
  // one day/three days로 자연스럽게 표기합니다.
  // 11 이상은 30 minutes처럼 숫자 표기를 유지합니다.
  if (digit === '1' && unit === 'month') {
    return 'a month';
  }

  if (digit === '1' && unit === 'hour') {
    return 'an hour';
  }

  const numberWord =
    TWO_PRO_KO_EN_NATIVE_NUMBER_WORDS_V54[sourceNumber] ||
    TWO_PRO_ENGLISH_SMALL_CARDINALS_V928[digit] ||
    digit;

  return `${numberWord} ${unit}${digit === '1' ? '' : 's'}`;
};

// ============================================================================
// ☆ TwoPro v5.8: 한국어 조사 문맥 엔진
// 은/는, 이/가, 을/를, (으)로, 과/와, 에서, 에, 으로부터/로부터를
// 문장 역할에 따라 분리하고 DB 유사 문장보다 먼저 번역합니다.
// ============================================================================
const twoProBuildDirectParticleBundleV58 = (
  source: string,
  slotType: 'N' | 'V' | 'ADJ' | 'PLACE'
): TwoProKoEnCandidateBundleV5 | null => {
  const normalizedSource =
    slotType === 'ADJ'
      ? twoProNormalizeKoreanAdjectiveV5(source)
      : slotType === 'V'
        ? twoProCanonicalKoreanVerbV56(source)
        : twoProNormalizeKoreanNounV5(source);

  if (!normalizedSource) {
    return null;
  }

  const priorities =
    TWO_PRO_KO_EN_LEXICAL_PRIORITIES_V5[normalizedSource] || [];

  const localCandidate =
    slotType === 'V'
      ? TWO_PRO_KO_EN_COMMON_VERBS[normalizedSource]
      : slotType === 'PLACE'
        ? TWO_PRO_KO_EN_PLACES[normalizedSource] ||
          TWO_PRO_KO_EN_COMMON_NOUNS[normalizedSource]
        : slotType === 'N'
          ? TWO_PRO_KO_EN_COMMON_NOUNS[normalizedSource]
          : null;

  const candidates = [
    ...priorities,
    ...(localCandidate ? [localCandidate] : []),
  ].filter(
    (candidate, index, values) =>
      candidate &&
      values.findIndex(
        (item) => item.toLowerCase() === candidate.toLowerCase()
      ) === index
  );

  if (!candidates.length) {
    return null;
  }

  return {
    source: normalizedSource,
    selected: candidates[0],
    candidates: candidates.slice(0, 6),
    referenceCandidates: candidates.slice(0, 6),
    confidence: priorities.length ? 0.99 : 0.95,
    slotType,
  };
};

const twoProGetParticleBundleV58 = async (
  source: string,
  slotType: 'N' | 'V' | 'ADJ' | 'PLACE',
  supabase: any
): Promise<TwoProKoEnCandidateBundleV5 | null> => {
  // =================================================================
  // ☆ TwoPro v9.91-safe: v5.8 조사 엔진의 명사 슬롯에서
  // 기존 로컬 대표명사를 최우선으로 보존하고,
  // 그 다음 rules-common-nouns.json의 SAFE 한국어 역색인을 사용합니다.
  //
  // 목적:
  // - '돈'처럼 로컬 맵에는 없지만 common-nouns SAFE에는 있는 명사가
  //   DB 후보(oof/argentus 등)로 내려가기 전에 대표 lemma(money)를 선택.
  // - 기존 TWO_PRO_KO_EN_COMMON_NOUNS의 결과는 전혀 바꾸지 않음.
  // - SAFE가 없으면 기존 DB 후보 검색 흐름을 그대로 유지.
  // =================================================================
  if (slotType === 'N') {
    const existingDirect =
      twoProBuildDirectParticleBundleV58(
        source,
        slotType
      );

    if (existingDirect) {
      return existingDirect;
    }

    const safeCommonNoun =
      twoProLookupKoreanSafeCommonNounV1(
        source
      );

    const safeLemma =
      String(
        safeCommonNoun?.lemma || ''
      ).trim();

    if (safeLemma) {
      return {
        source:
          twoProNormalizeKoreanNounV5(
            source
          ),
        selected: safeLemma,
        candidates: [safeLemma],
        referenceCandidates: [safeLemma],
        confidence: 0.995,
        slotType,
      };
    }
  }

  return (
    twoProBuildDirectParticleBundleV58(source, slotType) ||
    await twoProLookupBasicEnglishCandidatesV5(
      source,
      slotType,
      supabase
    )
  );
};

const twoProDefiniteNounPhraseV58 = (
  selected: string
): string => {
  const clean = String(selected || '').trim();

  if (!clean) return '';

  if (
    /^(?:a|an|the|some|my|your|his|her|our|their)\s+/i.test(clean) ||
    /^[A-Z]/.test(clean)
  ) {
    return clean;
  }

  return `the ${clean}`;
};

const twoProIndefiniteNounPhraseV58 = (
  source: string,
  selected: string
): string => {
  const cleanSource = twoProNormalizeKoreanNounV5(source);
  const clean = String(selected || '').trim();

  if (!clean) return '';

  if (
    /^(?:a|an|the|some|my|your|his|her|our|their)\s+/i.test(clean) ||
    /^[A-Z]/.test(clean)
  ) {
    return clean;
  }

  if (
    TWO_PRO_KO_EN_UNCOUNTABLE_NOUNS.has(clean.toLowerCase()) ||
    /들$/u.test(cleanSource) ||
    (/s$/i.test(clean) && !/ss$/i.test(clean))
  ) {
    return clean;
  }

  return `${twoProStartsWithVowelSound(clean) ? 'an' : 'a'} ${clean}`;
};

const twoProPossessiveDeterminerV58 = (
  subjectEn: string
): string => {
  const map: Record<string, string> = {
    I: 'my',
    you: 'your',
    he: 'his',
    she: 'her',
    we: 'our',
    they: 'their',
    it: 'its',
  };

  return map[String(subjectEn || '').trim()] || 'the';
};

const twoProReferenceWordsV58 = (
  bundles: Array<TwoProKoEnCandidateBundleV5 | null>
): TwoProKoEnReferenceWordV5[] => {
  const seen = new Set<string>();
  const result: TwoProKoEnReferenceWordV5[] = [];

  for (const bundle of bundles) {
    if (!bundle) continue;

    const item = twoProReferenceWordV5(bundle);
    if (!item) continue;

    const key = `${item.slot}::${item.source}`;
    if (seen.has(key)) continue;

    seen.add(key);
    result.push(item);
  }

  return result;
};


// ============================================================================
// ☆ TwoPro v6.0: 한영 다의어 문맥 판별 엔진
// 동일한 한국어 표면형을 목적어·주어·소유·장소·동사 문맥으로 구분합니다.
// 눈(eye/snow), 배(stomach/ship/pear), 차(car/tea/difference),
// 말(horse/words), 사과(apple/apology), 회의(meeting/doubt)를 문맥 우선 처리합니다.
// ============================================================================
