const twoProAnalyzeReportingPredicateV90 = (
  surface: string
): TwoProKoEnPredicateInfoV52 | null => {
  const normalized = String(surface || '')
    .replace(/[.?!]+$/g, '')
    .trim();

  const direct =
    TWO_PRO_REPORTING_SURFACE_FORMS_V90[
      normalized
    ];

  if (direct) {
    return { ...direct };
  }

  const generic =
    twoProAnalyzeEmbeddedPredicateV90(
      normalized
    );

  if (
    generic &&
    TWO_PRO_REPORTING_VERBS_V90[
      generic.base
    ]
  ) {
    return generic;
  }

  return null;
};

const twoProEmbeddedPredicateMetaV90 = (
  clauseText: string
): {
  explicitSubject: TwoProExplicitSubjectV62 | null;
  predicate: TwoProKoEnPredicateInfoV52 | null;
  predicateSurface: string;
} => {
  const explicitSubject =
    twoProExtractLeadingSubjectV62(
      clauseText
    );

  const body = explicitSubject
    ? explicitSubject.body
    : clauseText;

  const predicateSurface =
    body
      .split(/\s+/)
      .filter(Boolean)
      .pop() || '';

  return {
    explicitSubject,
    predicate:
      twoProAnalyzeEmbeddedPredicateV90(
        predicateSurface
      ),
    predicateSurface,
  };
};

const twoProTranslateSafeEmbeddedClauseV90 = async (
  restoredClause: string,
  quoteKind: TwoProEmbeddedQuoteKindV90,
  inheritedPronoun: TwoProExplicitSubjectV62['pronoun'],
  reportingTense: TwoProKoEnSimpleTenseV52
): Promise<{
  targetText: string;
  analysis: Array<{ ko: string; en: string }>;
  referenceWords: TwoProKoEnReferenceWordV5[];
  predicateBase?: string;
} | null> => {
  let clauseText =
    twoProNormalizeClauseTextV70(
      restoredClause
    );

  let meta =
    twoProEmbeddedPredicateMetaV90(
      clauseText
    );

  if (!meta.explicitSubject) {
    clauseText = `${twoProEmbeddedSubjectKoV90(
      inheritedPronoun
    )} ${clauseText}`;

    meta =
      twoProEmbeddedPredicateMetaV90(
        clauseText
      );
  }

  const embeddedPronoun =
    meta.explicitSubject?.pronoun ||
    inheritedPronoun;

  const subjectEn =
    twoProEmbeddedSubjectEnV90(
      embeddedPronoun
    );

  if (meta.predicate) {
    const verbEn =
      twoProSafeVerbEnV90(
        meta.predicate.base
      );

    if (verbEn) {
      let tense = meta.predicate.tense;
      let verbPhrase = '';

      if (quoteKind === 'future') {
        tense = 'future';
      } else if (
        reportingTense === 'past' &&
        tense === 'present'
      ) {
        // 오다·가다·도착하다처럼 발화 시점 이후의 예정 동작은
        // 과거 보고 동사 뒤에서 would + 원형으로 후퇴시킵니다.
        if (
          new Set([
            '오다',
            '가다',
            '도착하다',
            '시작하다',
            '끝나다',
          ]).has(meta.predicate.base)
        ) {
          verbPhrase = `would ${verbEn}`;
        } else {
          tense = 'past';
        }
      }

      if (!verbPhrase) {
        verbPhrase =
          twoProConjugateEnglishVerbV52(
            verbEn,
            tense,
            subjectEn
          );
      }

      return {
        targetText:
          twoProFinalizeEnglish(
            `${subjectEn} ${verbPhrase}`,
            clauseText
          ),
        analysis: [
          {
            ko:
              meta.explicitSubject?.source ||
              twoProEmbeddedSubjectKoV90(
                inheritedPronoun
              ),
            en: `${subjectEn} [QUOTE-SUBJECT]`,
          },
          {
            ko: meta.predicate.base,
            en: `${verbEn} [QUOTE-VERB]`,
          },
        ],
        referenceWords: [
          twoProEmbeddedReferenceWordV90(
            meta.predicate.base,
            verbEn,
            'V'
          ),
        ],
        predicateBase: meta.predicate.base,
      };
    }
  }

  if (meta.predicate) {
    const adjectiveEn =
      TWO_PRO_EMBEDDED_SAFE_ADJECTIVES_V90[
        meta.predicate.base
      ];

    if (adjectiveEn) {
      let adjectiveTense =
        meta.predicate.tense;

      if (
        reportingTense === 'past' &&
        adjectiveTense === 'present'
      ) {
        adjectiveTense = 'past';
      }

      const pluralSubject =
        ['we', 'you', 'they'].includes(
          embeddedPronoun
        );

      const beVerb = adjectiveTense === 'future'
        ? 'will be'
        : adjectiveTense === 'past'
          ? pluralSubject
            ? 'were'
            : 'was'
          : pluralSubject
            ? 'are'
            : 'is';

      return {
        targetText:
          twoProFinalizeEnglish(
            `${subjectEn} ${beVerb} ${adjectiveEn}`,
            clauseText
          ),
        analysis: [
          {
            ko:
              meta.explicitSubject?.source ||
              twoProEmbeddedSubjectKoV90(
                inheritedPronoun
              ),
            en: `${subjectEn} [QUOTE-SUBJECT]`,
          },
          {
            ko: meta.predicate.base,
            en: `${adjectiveEn} [QUOTE-ADJECTIVE]`,
          },
        ],
        referenceWords: [
          twoProEmbeddedReferenceWordV90(
            meta.predicate.base,
            adjectiveEn,
            'ADJ'
          ),
        ],
        predicateBase: meta.predicate.base,
      };
    }
  }

  if (quoteKind === 'copular') {
    const explicitSubject =
      twoProExtractLeadingSubjectV62(
        clauseText
      );

    if (!explicitSubject) {
      return null;
    }

    const copularMatch =
      explicitSubject.body.match(
        /^(.+?)(?:이다|입니다|이었다|였습니다)$/u
      );

    if (copularMatch) {
      const nounSource =
        twoProNormalizeKoreanNounV5(
          copularMatch[1]
        );

      const nounEn =
        twoProSafeNounEnV90(nounSource);

      if (nounEn) {
        const beVerb = reportingTense === 'past'
          ? ['we', 'you', 'they'].includes(
              embeddedPronoun
            )
            ? 'were'
            : 'was'
          : ['we', 'you', 'they'].includes(
              embeddedPronoun
            )
            ? 'are'
            : 'is';

        return {
          targetText:
            twoProFinalizeEnglish(
              `${subjectEn} ${beVerb} ${twoProIndefiniteNounPhraseV58(
                nounSource,
                nounEn
              )}`,
              clauseText
            ),
          analysis: [
            {
              ko: explicitSubject.source,
              en: `${subjectEn} [QUOTE-SUBJECT]`,
            },
            {
              ko: nounSource,
              en: `${nounEn} [QUOTE-COMPLEMENT]`,
            },
          ],
          referenceWords: [
            twoProEmbeddedReferenceWordV90(
              nounSource,
              nounEn,
              'N'
            ),
          ],
        };
      }
    }
  }

  // 목적어·장소가 포함된 인용절은 이미 검증된 단문 엔진을 재사용합니다.
  const existing =
    await twoProTryTranslateSingleClauseV70(
      clauseText
    );

  if (!existing) {
    return null;
  }

  return {
    targetText: existing.targetText,
    analysis: existing.analysis,
    referenceWords: existing.referenceWords,
    predicateBase:
      meta.predicate?.base,
  };
};

const twoProReportingVerbEnV90 = (
  baseKo: string,
  tense: TwoProKoEnSimpleTenseV52,
  subjectEn: string
): string | null => {
  const forms =
    TWO_PRO_REPORTING_VERBS_V90[baseKo];

  if (!forms) {
    return null;
  }

  if (tense === 'past') {
    return forms.past;
  }

  if (tense === 'future') {
    return `will ${forms.present}`;
  }

  return twoProConjugateEnglishVerbV52(
    forms.present,
    'present',
    subjectEn
  );
};

// ============================================================================
// ☆ TwoPro v9.43-safe: 베티 선물 완료 관형절
//
// 처리 범위:
// - 그의 생일에 그에게 멋진 선물을 사준 소녀는 베티였다.
// - 그에게 멋진 선물을 사준 소녀는 베티였다.
// - 그의 생일에 그에게 선물을 사준 소녀는 베티였다.
// - 그에게 선물을 사준 소녀는 베티였다.
//
// 안전 원칙:
// 1. 과거에 완료된 관형절 '-사준'은 목적·예정을 나타내는 to buy가 아니라
//    실제 행위를 나타내는 who bought로 번역합니다.
// 2. 멋진 선물/선물의 관사를 각각 a nice present/a present로 보충합니다.
// 3. 그의 생일에는 기존 예문의 의미를 유지해 on his birthday로 처리합니다.
// 4. 이 네 가지 제한 문형만 선제 처리하여 일반 사주다 문장을 가로채지 않습니다.
// ============================================================================
type TwoProBettyGiftAttributiveResultV943 = {
  targetText: string;
  analysis: Array<{
    ko: string;
    en: string;
  }>;
  referenceWords: any[];
  engine: string;
  matchedRule: string;
};

const twoProTryKoEnBettyGiftAttributiveV943 = (
  originalText: string
): TwoProBettyGiftAttributiveResultV943 | null => {
  const normalized = String(originalText || '')
    .normalize('NFC')
    .replace(/\s+/g, '')
    .replace(/[?.!,;:'"“”‘’()\[\]{}…·]/g, '')
    .trim();

  const match = normalized.match(
    /^(그의생일에)?그에게(멋진)?선물을사준소녀는베티였다$/u
  );

  if (!match) {
    return null;
  }

  const hasBirthday = Boolean(match[1]);
  const isNicePresent = Boolean(match[2]);

  const giftKo = isNicePresent
    ? '그에게 멋진 선물을 사준'
    : '그에게 선물을 사준';

  const giftEn = isNicePresent
    ? 'a nice present'
    : 'a present';

  let targetCore =
    `The girl who bought him ${giftEn}`;

  if (hasBirthday) {
    targetCore += ' on his birthday';
  }

  targetCore += ' was Betty';

  const referenceWords: any[] = [
    {
      source: '소녀는',
      selected: 'the girl',
      candidates: ['the girl'],
      slot: 'SUBJECT',
      confidence: 1,
      origin: 'route-v9.43',
    },
    {
      source: giftKo,
      selected: `who bought him ${giftEn}`,
      candidates: [
        `who bought him ${giftEn}`,
      ],
      slot: 'RELATIVE_CLAUSE',
      confidence: 1,
      origin: 'route-v9.43',
    },
  ];

  if (hasBirthday) {
    referenceWords.push({
      source: '그의 생일에',
      selected: 'on his birthday',
      candidates: ['on his birthday'],
      slot: 'TIME',
      confidence: 1,
      origin: 'route-v9.43',
    });
  }

  referenceWords.push({
    source: '베티였다',
    selected: 'was Betty',
    candidates: ['was Betty'],
    slot: 'PREDICATE_COMPLEMENT',
    confidence: 1,
    origin: 'route-v9.43',
  });

  const targetText = twoProFinalizeEnglish(
    targetCore,
    originalText
  );

  return {
    targetText,
    analysis: referenceWords.map(
      (item) => ({
        ko: item.source,
        en: `${item.selected} [${item.slot}]`,
      })
    ),
    referenceWords,
    engine:
      'betty-gift-relative-clause-ko-en-v9.43',
    matchedRule: hasBirthday
      ? isNicePresent
        ? 'BETTY_BIRTHDAY_NICE_PRESENT_V943'
        : 'BETTY_BIRTHDAY_PRESENT_V943'
      : isNicePresent
        ? 'BETTY_NICE_PRESENT_V943'
        : 'BETTY_PRESENT_V943',
  };
};


// ============================================================================
// ☆ TwoPro v9.53-safe: 범용 인칭주어 기반 청년 성장·변화 문형
//
// 핵심 목적:
// - 나는/우리는/너는/너희는/너희들은/그는/그녀는/그들은 등을
//   문장마다 별도 열거하지 않고 기존 twoProExtractLeadingSubjectV62를 재사용합니다.
// - '그 아이는'은 인칭대명사가 아닌 명사 주어이므로 이 문형의 명사 주어로 함께 처리합니다.
//
// 처리되는 본문:
// - 자라서 훌륭한 청년이 되었다
// - 자라서 청년이 되었다
// - 훌륭한 청년이 되었다
// - 청년이 되었다
//
// 안전 원칙:
// 1. 과거형 grew/became은 인칭에 따라 활용이 달라지지 않으므로
//    하나의 문형으로 모든 인칭대명사 주어를 처리합니다.
// 2. we/they/너희 계열은 영어 보어를 복수형 young adults로 조정합니다.
// 3. 기존 교재식 단수 번역 a fine youth / a youth는 유지합니다.
// 4. 이 문형만 Supabase 참고 문장 및 일반 검색보다 먼저 처리합니다.
